**2) Seasonality Analysis using Enhanced Sparklines**

Identify seasonal trends, sales peaks, and low-demand periods that may influence inventory and marketing decisions.


::: {.cell}

```{.r .cell-code}
monthly_report <- coffeechain %>%
  mutate(
    Year = year(Date),
    Month = month(Date, label = TRUE, abbr = TRUE)
  ) %>%
  filter(Year == 2013) %>%
  group_by(Product, Month) %>%
  summarise(
    Sales = sum(Sales, na.rm = TRUE),
    .groups = "drop"
  )

seasonality_data <- monthly_report %>%
  group_by(Product) %>%
  summarise(
    Min = min(Sales),
    Max = max(Sales),
    Average = mean(Sales),
    `Monthly Sales` = list(Sales),
    .groups = "drop"
  )

seasonality_data %>%
  gt() %>%
  fmt_number(
    columns = c(Min, Max, Average),
    decimals = 0
  ) %>%
  gt_plt_sparkline(
    column = "Monthly Sales",
    type = "points",
    same_limit = FALSE,
    palette = c("white", "white", "purple", "green", "white")
  ) %>%
  gt_theme_538()
```

