spark <- monthly_report %>%
  group_by(Product) %>%
  summarise(
    `Monthly Sales` = list(Sales),
    .groups = "drop"
  )

summary_stats <- monthly_report %>%
  group_by(Product) %>%
  summarise(
    Min = min(Sales),
    Max = max(Sales),
    Average = mean(Sales),
    .groups = "drop"
  )

bullet <- coffeechain %>%
  filter(Date >= "2013-01-01") %>%
  group_by(Product) %>%
  summarise(
    Target = sum(`Budget Sales`, na.rm = TRUE),
    Actual = sum(Sales, na.rm = TRUE),
    Achievement = Actual / Target,
    .groups = "drop"
  )

dashboard_data <- summary_stats %>%
  left_join(spark, by = "Product") %>%
  left_join(bullet, by = "Product") %>%
  arrange(desc(Achievement))

dashboard_data %>%
  gt() %>%
  fmt_number(
    columns = c(Min, Max, Average, Actual, Target),
    decimals = 0
  ) %>%
  fmt_percent(
    columns = Achievement,
    decimals = 1
  ) %>%
  gt_plt_sparkline(
    column = "Monthly Sales",
    type = "points",
    same_limit = FALSE,
    palette = c("white", "white", "purple", "green", "white")
  ) %>%
  gt_plt_bullet(
    column = Actual,
    target = Target,
    width = 28,
    palette = c("lightblue", "black")
  ) %>%
  gt_theme_538()
